def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe_bid = 18.0 if hp > 3 else 45.0
        return float(max(0.0, min(budget, safe_bid)))

    prev_bids = []
    threatening_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 90.0:
                threatening_bids.append(float(bid))
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
            desperate_count += 1
        if opp.get('budget', 0) >= 700:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    total_players = 1 + len(alive_opponents)
    capacity = int(supply // WATER_REQ)
    scarce = capacity < total_players
    very_scarce = capacity <= 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1
    if day >= 8:
        urgency += 1

    if very_scarce:
        target = max(118.0, highest_prev + 4.0, avg_prev + 8.0)
        if urgency >= 3:
            target = max(target, 132.0)
        if rich_count >= 2:
            target += 6.0
    elif scarce:
        if urgency >= 3:
            target = max(96.0, highest_prev + 2.0)
        elif urgency >= 1:
            target = max(72.0, avg_prev * 0.8)
        else:
            target = 38.0 if highest_prev >= 100.0 else 52.0
    else:
        if urgency >= 3:
            target = 70.0
        elif urgency >= 1:
            target = 34.0
        else:
            target = 16.0

    if desperate_count >= 2 and scarce:
        target += 8.0

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 35.0
    affordable = max(0.0, budget - reserve_floor)
    if urgency >= 3:
        affordable = budget

    bid = min(target, affordable if affordable > 0 else budget)

    if hp <= 1 or no_water_days >= 2:
        bid = min(budget, max(bid, 145.0))
    elif hp <= 3 and scarce:
        bid = min(budget, max(bid, 110.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Collect alive opponents and their yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        # If alone, bid to ensure survival with minimal spend
        target = DAILY_SALARY * 0.35
        return max(0.0, min(my_budget, target))

    yesterday_bids = []
    yesterday_hp_after = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                yesterday_hp_after.append(float(hp_after))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    # If opponents were bidding very high yesterday, we must not underbid too much.
    # Cindy/Eric averaged ~111; treat >=110 as high pressure.
    high_pressure = highest_prev_bid >= 110.0

    # Supply pressure: higher supply reduces urgency; lower supply increases urgency.
    # Map supply into [0,1]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_factor = 0.5
    else:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_factor < 0.0:
            supply_factor = 0.0
        if supply_factor > 1.0:
            supply_factor = 1.0

    # Base bid level: moderate around 0.6*salary when supply is medium.
    # Adjust upward if high pressure or if my hp/no-water-days are critical.
    bid = DAILY_SALARY * (0.62 + 0.10 * supply_factor)

    # Reaction to my health
    if my_hp <= 2.0 or my_no_water_days >= 2:
        bid = DAILY_SALARY * 0.92
    elif my_hp <= 4.0:
        bid = DAILY_SALARY * 0.75
    elif my_hp <= 6.0:
        bid = DAILY_SALARY * 0.66

    # Reaction to opponents' yesterday bids
    if high_pressure:
        # Bid closer to their pressure ceiling but still conservative.
        bid = max(bid, min(DAILY_SALARY * 0.75, highest_prev_bid * 0.95))

    # If my budget is low, cap aggressively but still try to win if critical.
    if my_budget <= DAILY_SALARY * 0.25:
        if my_hp <= 4.0 or my_no_water_days >= 2:
            bid = min(my_budget, DAILY_SALARY * 0.95)
        else:
            bid = min(my_budget, DAILY_SALARY * 0.45)

    # Final clamp
    if my_budget < 0.0:
        my_budget = 0.0
    if bid < 0.0:
        bid = 0.0

    return min(my_budget, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid: low if healthy, high if desperate
    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.7
    else:
        base_bid = DAILY_SALARY * 0.4

    # Adjust based on opponent's past maximum bid
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        # Need to ensure we get water if supply is low
        if supply < 20:
            # competitive scenario: outbid the highest previous bid by a small margin
            required = max(base_bid, max_prev_bid + 2.0)
        else:
            required = max(base_bid, max_prev_bid * 0.9)
    else:
        required = base_bid

    # Ensure we don't exceed budget and stay positive
    final_bid = min(my_budget, required)
    # Also ensure non-negative
    final_bid = max(0, final_bid)
    return int(final_bid)
